@custom-variant dark (&:is(.dark *));
@theme {
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  /* Sans and mono are deliberately NOT in `@theme inline`. Inline theme vars
   * are substituted into every utility at build time, so `font-sans`,
   * `font-mono` and the `html` default font compiled to the literal Geist
   * stack and ignored the inline `--font-sans` / `--font-mono` that
   * `lib/appearance/typography-applier.tsx` writes onto <html>. As plain
   * theme vars the utilities read `var(--font-sans)` at runtime, so the
   * user's Typography picks reach chat body text and code. */
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  /* Spring easings for CSS-only motion, sampled from the same springs as
   * `SPRING_POP` / `SPRING_DRAG` (`packages/plugin-ui/src/motion-tokens.ts`)
   * so a checkbox or switch moves with the personality a motion component
   * would. `ease-spring-pop` (380/18, ~0.46 damping) overshoots once and
   * settles: pair it with `duration-(--duration-spring-pop)`, for confirmations.
   * `ease-spring-drag` (1200/80, over-damped) lands without rebound: pair it
   * with `duration-(--duration-spring-drag)`, for things held or placed. */
  --ease-spring-pop: linear(
    0,
    0.0668,
    0.231,
    0.4426,
    0.6604,
    0.8552,
    1.0093,
    1.1157,
    1.1753,
    1.1948,
    1.1839,
    1.1531,
    1.1123,
    1.0697,
    1.0312,
    1.0004,
    0.9788,
    0.9665,
    0.9621,
    0.9638,
    0.9696,
    0.9774,
    0.9857,
    0.9933,
    0.9995,
    1.0038,
    1.0064,
    1.0074,
    1.0071,
    1.006,
    1
  );
  --ease-spring-drag: linear(
    0,
    0.1451,
    0.3714,
    0.5619,
    0.7013,
    0.7982,
    0.8643,
    0.9089,
    0.9389,
    0.959,
    0.9725,
    0.9816,
    0.9877,
    0.9917,
    0.9945,
    1
  );
  --ease-ink: cubic-bezier(0.215, 0.61, 0.355, 1);
}
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  /* Workflow category & status semantic tokens. Each is referenced by the
     `--wf-*` variables in `:root` / `.dark` so dark-mode tracking is automatic
     once a component switches from `bg-emerald-500/15` to `bg-wf-trigger/15`. */
  --color-wf-trigger: var(--wf-trigger);
  --color-wf-action: var(--wf-action);
  --color-wf-ai: var(--wf-ai);
  --color-wf-flow: var(--wf-flow);
  --color-wf-data: var(--wf-data);
  --color-wf-io: var(--wf-io);
  --color-wf-annotation: var(--wf-annotation);
  --color-wf-status-running: var(--wf-status-running);
  --color-wf-status-succeeded: var(--wf-status-succeeded);
  --color-wf-status-failed: var(--wf-status-failed);
  --color-wf-status-skipped: var(--wf-status-skipped);
  --color-wf-status-waiting: var(--wf-status-waiting);
  --color-wf-status-idle: var(--wf-status-idle);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  /* Proportional, not absolute (ADR-0148). shadcn ships these as fixed ±px
     offsets, which means a base of 0 still leaves `rounded-xl` at 4px — so
     "no rounded corners" was never actually reachable, on this chain or the
     named one below. Multipliers land on exactly the same 6 / 8 / 10 / 14px at
     the default 0.625rem base, and collapse to 0 with it. The ramp's shape only
     differs from before at a hand-set base, where scaling proportionally is
     what a radius *scale* should do anyway. */
  --radius-sm: max(0px, calc(var(--radius) * 0.6));
  --radius-md: max(0px, calc(var(--radius) * 0.8));
  --radius-lg: max(0px, var(--radius));
  --radius-xl: max(0px, calc(var(--radius) * 1.4));
  /* ADR-0148 — named radius scale. These ALIAS the derived chain above rather
     than replacing it, so the ~1,777 existing `rounded-sm/md/lg/xl` sites keep
     tracking `--radius` with zero migration. The values are exact at the
     default base (0.625rem = 10px): control 8px (identical to `--radius-md`),
     panel 12px, stage 14px (identical to `--radius-xl`) — the same 8/12/14
     scale `cognia-labs/cognia-website:app/globals.css` pins for the marketing site. Multipliers rather
     than ±px offsets so a 0 base really does square every step; `max(0px, …)`
     stays as a guard against a plugin theme writing a negative `--radius`. */
  --radius-control: max(0px, calc(var(--radius) * 0.8));
  --radius-panel: max(0px, calc(var(--radius) * 1.2));
  --radius-stage: max(0px, calc(var(--radius) * 1.4));
  /* Pills are their own axis: `--radius` going to 0 must not square a status
     dot or a spinner. Only surfaces that opt into `rounded-pill` follow the
     style pack. */
  --radius-pill: var(--pill-radius);
  --color-effort-ultra: var(--effort-ultra);
  --color-effort-ultra-muted: var(--effort-ultra-muted);
  --color-brand-action: var(--brand-action);
  --color-brand-approval: var(--brand-approval);
  --color-brand-wash: var(--brand-wash);
}
